-- ============================================================
-- AIRPORTELs SOP Hub — CONSOLIDATED content migration (batch 1 + 2)
--   * Terms & Conditions -> 2026 bilingual TH/EN (archive 2025, guarded)
--   * Update late-pickup discount SOP (+figures)
--   * Insert 12 new SOP documents
--   * All figures/screenshots served from /public/sop/* (already deployed)
-- Small + idempotent. Run ONCE in the Supabase SQL Editor.
-- ============================================================
begin;

-- ===== terms-and-conditions-2025: archive current (guarded) then update =====
insert into sop.documents (slug, title, summary, category_id, content_html, cover_image, tags, status, is_onboarding, onboarding_order, version)
select 'terms-and-conditions-2025-archive', title || ' — เก็บถาวร ปี 2025 (Archive)', summary, category_id, content_html, cover_image,
       coalesce(tags,'{}') || array['archive'], 'draft', false, null, version
from sop.documents where slug = 'terms-and-conditions-2025'
  and not exists (select 1 from sop.documents where slug = 'terms-and-conditions-2025-archive');

update sop.documents set
  title = 'ข้อกำหนดและเงื่อนไขการให้บริการ 2026 (Terms & Conditions)', summary = 'ข้อกำหนดและเงื่อนไขมาตรฐานการใช้บริการของบริษัท แอร์พอเทลส์ อินเตอร์เนชันแนล จำกัด ปี 2026 (อัปเดต 29/04/2026) — แสดงสองภาษา ไทย/อังกฤษ ตามปุ่มเปลี่ยนภาษา ครอบคลุมการยอมรับเงื่อนไข ราคาและการชำระเงิน ความรับผิดชอบ สิ่งของต้องห้าม การจอง/ยกเลิก/คืนเงิน และค่าชดเชย', content_html = '<style>[lang="en"] .sop-lang-th{display:none}[lang="th"] .sop-lang-en{display:none}</style><div class="sop-lang-th"><blockquote><p><strong>อัปเดตล่าสุด:</strong> 29/04/2026 &nbsp;·&nbsp; เอกสารนี้แสดงสองภาษา — กดปุ่ม <strong>EN/TH</strong> ด้านซ้ายเพื่อสลับภาษา</p></blockquote>
<h3>Last update: 29/04/26</h3>
<h3>ข้อกำหนดและเงื่อนไขมาตรฐานการใช้บริการ</h3>
<p>การยอมรับเงื่อนไขและข้อกำหนดของบริษัท แอร์พอเทลส์ อินเตอร์เนชันแนล จำกัด กรุณาอ่านเงื่อนไขและข้อกำหนดเหล่านี้อย่างละเอียดก่อนที่คุณจะเข้าถึงและใช้บริการของเรา บริการของเรามีให้ บริการเฉพาะในเงื่อนไขที่ผู้เข้าร่วมบริการยอมรับเงื่อนไขและข้อกำหนดของเรา หากคุณไม่เห็นด้วยกับเงื่อนไขต่อไปนี้ กรุณาอย่าเข้าถึงหรือใช้บริการของเรา ขอให้ทราบว่าหากการจองหรือการเข้าร่วมใช้บริการของคุณทำโดยบุคคลที่ สามและเป็นในนามของคุณ นั่นหมายความว่าคุณยอมรับและเคารพเงื่อนไขและข้อกำหนดเหล่านี้รวมถึงนโยบาย</p>
<h3>ความเป็นส่วนตัวของเรา</h3>
<p>บริการของเรามีให้บริการเฉพาะสำหรับผู้ใช้ที่มีอายุ 18 ปีขึ้นไปและเป็นผู้ใหญ่ตามกฎหมายไทย ด้วยการใช้และเข้าถึง เว็บไซต์ แอปพลิเคชัน บริการของเรา คุณรับประกันว่าคุณมีอายุ 18 ปีขึ้นไป ยอมรับและเคารพเงื่อนไขและนโยบาย ของเรา และสามารถทำสัญญากับบริษัท แอร์พอเทลส์ อินเตอร์เนชันแนล จำกัด ได้อย่างอิสระ</p>
<h3>องค์กร</h3>
<p>บริษัท แอร์พอเทลส์ อินเตอร์เนชันแนล จำกัด เป็นองค์กรที่จดทะเบียนในราชอาณาจักรไทย ภายใต้เลขทะเบียน 0105565098687 และมีสำนักงานจดทะเบียนที่ 6 หมู่บ้านไพลินปาร์ค ซอยรัตนาธิเบศร์ 28 แยก 2 ตำบลบางกระสอ</p>
<h3>อำเภอเมืองนนทบุรี จังหวัดนนทบุรี 11000</h3>
<h3>ราคาและการเรียกเก็บเงิน</h3>
<p>การกำหนดราคา การทำธุรกรรม หรือการกระทำใดๆ ที่เกี่ยวข้องกับเงินจะทำได้เฉพาะผ่านเว็บไซต์และ/หรืออีเมลหรือ ที่เคาน์เตอร์ของเรา (แผนกต้อนรับ) ในรายการต่อไปนี้ โปรดทราบว่าคำขอใดๆ สำหรับเงิน ผลประโยชน์ หรือการทำ ธุรกรรมใดๆ ที่ไม่ได้เกิดขึ้นที่สถานที่หรือช่องทางที่เราแต่งตั้งไม่ได้รับอนุญาตจากเรา ราคาของบริการจะถูกเปิดเผยในรายการผ่านช่องทางของเรา เราอาจเปลี่ยนแปลงราคา แต่ราคาจะถูกตั้งไว้เมื่อมี การยืนยันการจอง และราคาที่ถูกแสดงทั้งหมดนั้นรวมภาษีมูลค่าเพิ่มแล้ว คำขอเพิ่มเติมใด ๆ ที่ไม่ได้รวมอยู่ในการ จองหรือการทำธุรกรรมเดียวกันจะถือเป็นคำสั่งซื้อใหม่ และราคาอาจแตกต่างกัน การทำธุรกรรมทั้งหมดสามารถ ชำระได้ด้วยบัตรเครดิต บัตรเดบิต และเงินสด โดยเป็นค่าเงินบาทไทย (฿) วิธีการชำระเงินมีดังนี้</p>
<h3>ออนไลน์</h3>
<ul><li>บัตรเครดิต/บัตรเดบิต (เฉพาะบัตรที่ออกโดย VISA, MASTER และ JCB)</li><li>Paypal</li><li>Alipay (เฉพาะผู้ใช้จากแผ่นดินใหญ่จีน)</li></ul>
<h3>ที่แผนกต้อนรับ AIRPORTELs (ประเทศไทย)</h3>
<ul><li>เงินสดเท่านั้นใน THB, เงินบาทไทย (฿)</li><li>บัตรเครดิต/บัตรเดบิต (เฉพาะบัตรที่ออกโดย VISA, MASTER, JCB และ UNION PAY)</li><li>Alipay (เฉพาะผู้ใช้จากแผ่นดินใหญ่จีน)</li><li>WeChat Pay (เฉพาะผู้ใช้จากแผ่นดินใหญ่จีน)</li><li>การโอนเงินไร้สาย</li><li>Paypal</li><li>Alipay (จีน)</li><li>PromptPay (ประเทศไทย)</li></ul>
<p>กระบวนการทั้งหมดของบริการ ตั้งแต่การจองจนถึงการเรียกเก็บเงินควรทำให้เสร็จสิ้นโดยใช้ชื่อและบุคคลเดียวกัน หนังสือเดินทางจริงหรือเอกสารรับรองการระบุตัวตนอื่น ๆ ที่ได้รับการยอมรับจะถูกขอให้แสดงเมื่อทำการทำธุรกรรม ตาชั่งที่ใช้สำหรับการชั่งน้ำหนักและการคำนวณบิลได้รับการบำรุงรักษาและปฏิบัติตามมาตรฐาน ISO 9001 เมื่อคุณ ยอมรับที่จะใช้บริการ คุณยังตกลงกับผลลัพธ์ที่ได้โดยตาชั่งของเรา เราจะจัดทำใบแจ้งหนี้ที่ถูกต้องให้คุณตามน้ำ</p>
<h3>หนักที่เราวัดได้</h3>
<p>คุณจะต้องได้รับใบเสร็จการชำระเงินในรูปแบบแข็งหรืออ่อนหลังจากการทำธุรกรรมเสร็จสิ้นเสมอ</p>
<h3>ใบเสร็จรับเงิน</h3>
<p>รายละเอียดและข้อมูลเกี่ยวกับราคาของบริการจะถูกเปิดเผยในใบแจ้งหนี้เมื่อการเรียกเก็บเงินได้รับการยืนยัน และจะ ไม่มีการเรียกเก็บค่าธรรมเนียมเพิ่มเติม เรายินดีให้คำอธิบายหากมีคำสั่งใดๆ จากบริการของเราที่ไม่ชัดเจน บุคคลที่ ใช้บริการควรเป็นบุคคลเดียวกับที่รับกระเป๋าหรือสัมภาระ ราคาที่ระบุในใบแจ้งหนี้ (ถ้ามี) และใบเสร็จรับเงินควรตรง กัน ใบเสร็จรับเงินจะถูกมอบให้เมื่อการทำธุรกรรมเสร็จสิ้นและคุณยอมรับเงื่อนไขและข้อกำหนดที่เรากำหนดไว้ การ รับใบเสร็จรับเงินหมายความว่าคุณยอมรับว่าการให้บริการได้สิ้นสุดแล้ว</p>
<h3>ความรับผิดชอบของ AIRPORTELs</h3>
<p>เรามอบและให้บริการตามที่ระบุไว้ในเว็บไซต์, แอปพลิเคชัน และเอกสารที่เคาน์เตอร์ของเรา หากเราไม่สามารถส่งมอบ การจัดส่งตามเวลาที่กำหนดไว้ เราจะคืนเงิน 100% ให้แก่คุณ หากเราไม่สามารถส่งมอบการจัดส่งขาออกตามเวลาที่ กำหนดไว้ เราจะรับผิดชอบในการชำระเงินที่จำเป็นเพื่อส่งกระเป๋าของคุณไปยังปลายทางที่คุณกำหนด เราจะแจ้งให้ คุณทราบถึงการเปลี่ยนแปลงใดๆ ที่อาจส่งผลกระทบต่อคุณผ่านช่องทางการติดต่อที่คุณให้ไว้</p>
<h3>ความรับผิดชอบของผู้ใช้</h3>
<p>คุณยินยอมว่าคุณจะไม่บรรจุสิ่งของที่ต้องห้าม ตามที่ระบุในหัวข้อรายการที่ถูกห้าม ในกระเป๋าที่จะทำการขนส่งหรือรับ ฝาก และบริการถูกใช้อย่างเหมาะสม คุณรับผิดชอบต่อการสูญเสียหรือความเสียหายที่เกิดจากการใช้งานที่ไม่ถูกต้อง หรือการละเมิดเงื่อนไขและข้อกำหนดของเรา ใบรับรองและใบเสร็จควรถูกเก็บรักษาโดยคุณเองและพร้อมที่จะตรวจ สอบเมื่อคุณทำการเรียกเก็บเงินหรือเช็กเอาต์ที่เคาน์เตอร์ของเรา คุณยืนยันว่าข้อมูลที่คุณให้ไว้กับเรานั้นถูกต้องและ ได้รับการยืนยันโดยคุณเอง ไม่ว่าจะเป็นข้อมูลที่คุณให้ไว้ด้วยตัวเองหรือโดยบุคคลที่ได้รับอนุญาต หลักฐานหรือใบรับ รอง (บัตรเครดิต/บัตรเดบิต หรือหนังสือเดินทาง) ของลายเซ็นหรือการระบุตัวตนของคุณอาจถูกขอโดยเจ้าหน้าที่</p>
<h3>ของเราเพื่อยืนยันการระบุตัวตนของคุณ</h3>
<h3>นโยบายการจัดส่งและการจัดการความปลอดภัย</h3>
<p>บริการทั้งหมดของเราควรถูกใช้ด้วยวัตถุประสงค์ที่ถูกกฎหมาย โดยการใช้บริการจัดส่งของเรา คุณตกลงกับ เงื่อนไขของเราและเคารพกฎหมายของราชอาณาจักรไทย เราจะไม่ทำลายกระเป๋าของคุณด้วยวัตถุประสงค์ที่ผิด กฎหมาย แต่ในกรณีที่จำเป็น เราจะร่วมมือกับหน่วยงานราชการหรือหน่วยงานของรัฐบาลไทยเพื่อการสอบสวนและ ป้องกันการกระทำผิดกฎหมาย หากมีการตรวจพบสิ่งของที่น่าสงสัย ผิดกฎหมาย มีความเสี่ยง หรืออันตราย จากการ แจ้งของหน่วยงานทางการไทยหรือจากการค้นพบโดยเครื่องสแกนเอกซเรย์หรือการตรวจสอบที่ไม่ทำลายสิ่งของ คุณอาจถูกขอให้ยอมให้กระเป๋าของคุณถูกตรวจสอบหรือสอบสวนโดยเจ้าหน้าที่ของเรา หากคุณปฏิเสธที่จะทำเช่น นั้น เราอาจปฏิเสธที่จะให้บริการคุณเพื่อเหตุผลด้านความปลอดภัย เรามีสิทธิ์ปฏิเสธและยกเลิกคำขอ การจอง การ สำรองห้องพัก หรือบริการอื่นๆ ของคุณหากคุณละเมิดเงื่อนไขและ/หรือถูกสงสัยว่ากระทำการที่ผิดกฎหมาย มีความ เสี่ยง หรืออันตราย โดยไม่มีการคืนเงิน เพื่อวัตถุประสงค์ด้านความปลอดภัย เราอาจร่วมมือกับหน่วยงานที่ได้รับ อนุญาตเพื่อตรวจสอบพัสดุ กระเป๋า หรือภาชนะใดๆ ในรูปแบบใดก็ได้ที่เราจัดส่งหรือเก็บไว้ กระเป๋าธรรมดาถูกนิยามว่ามีแต่ละด้าน (ความกว้าง ความยาว และความสูง) หรือเส้นผ่าศูนย์กลางของกระเป๋ารวม กันในทุกมิติ ไม่เกิน 200 ซม. และน้ำหนักของแต่ละชิ้นของกระเป๋าไม่ควรเกิน 25 กิโลกรัม</p>
<h3>กิจกรรมที่ไม่สามารถควบคุมได้</h3>
<p>เราไม่รับผิดชอบในการไม่สามารถส่งมอบบริการและดูแลกระเป๋าของคุณในกรณีที่เกิดจากบุคคลที่สามหรือ สถานการณ์ที่อยู่นอกเหนือการควบคุมของเราดังต่อไปนี้:</p>
<ul><li>การไม่สามารถเป็นไปตามข้อกำหนดด้านความปลอดภัยการบิน</li><li>การไม่สามารถจัดส่งกระเป๋าของคุณให้ถึงสนามบินได้ทันเวลา</li><li>การไม่สามารถจัดส่งกระเป๋าของคุณให้ถึงโรงแรมได้ทันเวลา</li><li>การไม่สามารถจอง สำรอง หรือยกเลิกบริการของเราได้ทันเวลา</li><li>การกระทำของหน่วยงานราชการหรือองค์กรทางการ (เช่น ตำรวจ ศุลกากร ผู้ดำเนินการสนามบิน และหน่วย</li></ul>
<h3>งานการบิน)</h3>
<ul><li>การหยุดชะงักของการขนส่งทางบกและทางอากาศระดับภูมิภาคหรือชาติ</li><li>ภัยธรรมชาติ (เช่น น้ำท่วม แผ่นดินไหว สึนามิ หรือไต้ฝุ่น)</li><li>สถานการณ์ที่ไม่สามารถควบคุมได้ที่เกิดจากบุคคลที่สาม (เช่น จลาจล การประท้วง ภัยไฟ การสอบสวนโดย</li></ul>
<h3>หน่วยงานที่ได้รับอนุญาต)</h3>
<ul><li>การแตกหักหรือสูญหายของกระเป๋าหรือทรัพย์สินของคุณโดยการกระทำของบุคคลที่สามซึ่งอยู่นอกเหนือการ</li></ul>
<h3>ควบคุมของเรา</h3>
<h3>รายการที่ถูกห้าม</h3>
<ul><li>สินค้าที่มีส่วนผสมของแอลกอฮอล์</li><li>สินค้าอันตราย วัตถุอันตราย</li><li>ของที่มีมูลค่าสูง เช่น เพชร พลอย ทองคำ</li><li>อาวุธปืนที่หรือสิ่งเทียบอาวุธและของมีคม</li><li>เงินสดและสิ่งต่างๆ ที่สามารถทดแทนเงินสดได้ เช่น เช็ค ธนบัตร หรือตราสารหนี้</li><li>สินค้าเน่าเสียได้ เช่น พืช ผัก ผลไม้ เนื้อสัตว์</li><li>พืชพันธุ์ เมล็ดพันธุ์พืช ไม้ต้องห้ามบางประเภท</li><li>วัตถุลามกอนาจาร และสื่อลามกทุกชนิด</li><li>สิ่งที่เป็นอันตรายทางชีวภาพ น้ำลาย เชื้อโรค เชื้อแบคทีเรีย เชื้อไวรัส สารกัมมันตภาพรังสี สารพิษ</li><li>สมุนไพรที่ขึ้นทะเบียนเป็นยา เช่นยาดม ยาหม่อง</li><li>ผลิตภัณฑ์จากสัตว์ที่ไม่มีใบอนุญาต (ในบางประเทศ)</li><li>สินค้าที่เป็นถ่านหรือแบตเตอรี่ทุกชนิด</li><li>กระเป๋าเดินทาง (ที่ไม่ได้บรรจุในกล่องพัสดุ) ห้ามล็อค หรือใส่รหัสล็อค</li><li>ยาสูบและผลิตภัณฑ์จากยาสูบ</li><li>วัตถุไวไฟและสารเคมีที่สามารถก่อประกายไฟและระเบิดได้</li><li>สลากกินแบ่ง, ลอตเตอรี่ หรือสื่อการพนันต่างๆ</li><li>ยา และสิ่งเสพติดผิดกฎหมาย ยาม้า ไอซ์ หรือแม้กระทั่งกัญชา</li><li>สัตว์ ที่มีชีวิตต่างๆ รวมถึงปลาและนก</li><li>เอกสารข้อมูลบุคคล เช่น พาสปอร์ต บัตรประชาชน บัตรเอทีเอ็ม บัญชีธนาคาร</li><li>สินค้าละเมิด ลิขสิทธิ์ สินค้าปลอมหรือลอกเลียนแบบเครื่องหมายการค้า</li><li>องค์พระ พระเครื่อง เทวรูป และวัตถุโบราณต่างๆ</li><li>ชิ้นส่วนมนุษย์ รวมถึงเถ้าอัฐ</li><li>อุปกรณ์อิเล็กทรอนิกส์ ที่เสี่ยงเสียหาย และแตกหักง่าย เช่น โทรศัพท์, Laptop, จอ, กล้อง และอื่นๆ</li></ul>
<h3>ความรับผิดของ AIRPORTELs</h3>
<p>สำหรับกระเป๋าที่มีป้ายกำกับและคำสั่งซื้อที่ได้รับการยืนยัน เราจะรับรองว่าการจัดส่งหรือบริการจะถูกจัดส่งหรือให้ บริการตามเวลา ไปยังจุดหมายปลายทางและผู้รับที่ถูกต้อง หากเราไม่สามารถปฏิบัติตามสัญญาได้ การชดเชยควรจะ ไม่เกินราคาหรือใดๆ ที่มีมูลค่า 50,000 บาท* สำหรับหนึ่งคำสั่งซื้อ</p>
<ul><li>เราจะไม่รับผิดชอบใดๆ สำหรับสิ่งของที่เปราะบางหรือที่เสื่อมสภาพได้ง่ายที่อยู่ในกระเป๋าที่เราจัดส่ง</li><li>เราจะไม่รับผิดชอบใดๆ สำหรับสิ่งของที่ถูกห้ามหรือเนื้อหาในกระเป๋าที่เราจัดส่ง</li><li>เราจะไม่รับผิดชอบใดๆ ในกรณีที่คุณละเมิดหรือฝ่าฝืนเงื่อนไขของเราหรือกฎหมายไทย</li><li>เราจะไม่รับผิดชอบใดๆ สำหรับสิ่งของที่ถูกแยกออก อันตราย หรือถูกห้ามหรือเนื้อหาในกระเป๋าที่เราจัดส่ง</li><li>เราจะไม่รับผิดชอบใดๆ สำหรับทรัพย์สินหรือของมีค่าของคุณก่อนที่กระเป๋าหรืออุปกรณ์จะถูกมอบให้กับเราใน</li></ul>
<h3>สถานการณ์ใดๆ</h3>
<ul><li>เราจะไม่รับผิดชอบใดๆ สำหรับทรัพย์สินหรือของมีค่าของคุณหลังจากการทำธุรกรรมสิ้นสุดและกระเป๋าถูกกู้คืน</li></ul>
<h3>โดยลูกค้า</h3>
<ul><li>เราจะไม่รับผิดชอบใดๆ สำหรับทรัพย์สินหรือของมีค่าของคุณหากมีบุคคลใดๆ รวมถึงคุณเอง แสดงหลักฐานที่</li></ul>
<h3>ถูกต้องเพื่อเรียกคืนของมีค่าของคุณ</h3>
<ul><li>เราจะไม่รับผิดชอบใดๆ สำหรับทรัพย์สินหรือของมีค่าของคุณหากมีบุคคลใดๆ รวมถึงคุณเอง ที่ทำการกู้คืนของ</li></ul>
<h3>มีค่าของคุณออกจากเคาน์เตอร์ของเราที่ปลายทาง</h3>
<ul><li>มูลค่าทางอารมณ์ของสิ่งของจะไม่เกี่ยวข้องกับการประเมินมูลค่า</li><li>การติดของประดับใดๆ บนกระเป๋า เช่น ป้ายชื่อ ตุ๊กตาประดับ หมอน หรือกระเป๋าเล็ก ไม่ได้รับการรับประกันในเรื่อง</li></ul>
<h3>สภาพหรือการสูญหาย</h3>
<ul><li>ในกรณีที่กระเป๋าหรือเป้ของคุณเสียหาย และได้รับการยืนยันว่าความเสียหายและการสูญเสียเกิดขึ้นระหว่างการ</li></ul>
<p>ขนส่งโดยยานพาหนะของบริษัท แอร์พอร์เทลส์ อินเตอร์เนชันแนล จำกัด การชดเชยจะอ้างอิงตามตารางที่</p>
